const test = require("node:test");
const assert = require("node:assert");

const { startServer, api } = require("./helpers");

test("bulk-delete: removes all links when every slug exists", async () => {
  const { base, close } = startServer();
  try {
    await api(base, "POST", "/api/links", { url: "https://a.example.com", slug: "link-a" });
    await api(base, "POST", "/api/links", { url: "https://b.example.com", slug: "link-b" });

    const resp = await api(base, "POST", "/api/links/bulk-delete", { slugs: ["link-a", "link-b"] });
    assert.strictEqual(resp.status, 200);

    const checkA = await api(base, "GET", "/api/links/link-a");
    const checkB = await api(base, "GET", "/api/links/link-b");
    assert.strictEqual(checkA.status, 404);
    assert.strictEqual(checkB.status, 404);
  } finally {
    await close();
  }
});

test("bulk-delete: is atomic - a missing slug leaves everything untouched", async () => {
  const { base, close } = startServer();
  try {
    await api(base, "POST", "/api/links", { url: "https://a.example.com", slug: "link-a" });
    await api(base, "POST", "/api/links", { url: "https://b.example.com", slug: "link-b" });

    const resp = await api(base, "POST", "/api/links/bulk-delete", {
      slugs: ["link-a", "link-b", "does-not-exist"],
    });
    assert.strictEqual(resp.status, 404);

    const checkA = await api(base, "GET", "/api/links/link-a");
    const checkB = await api(base, "GET", "/api/links/link-b");
    assert.strictEqual(checkA.status, 200);
    assert.strictEqual(checkB.status, 200);
  } finally {
    await close();
  }
});

